class Fib(object):
    def __init__(self, fim):
        self.fim = fim
        self.c = 0

    def __iter__(self):
        return FibIter(self.fim)


class FibIter(object):
    def __init__(self, fim):
        self.fim = fim
        self.c = 0
        self.a, self.b = 0, 1

    def __next__(self):
        if self.c < self.fim:
            self.a, self.b = self.b, self.a + self.b
            self.c += 1
            return self.b
        else:
            raise StopIteration


