from math import pi
from math import sqrt

class ChartObject:
    def __init__(self, fill_color, filled, contour_color):
        self.fill_color = fill_color
        self.filled = filled
        self.contour_color = contour_color

class Rectangle(ChartObject):
    def __init__(self, fill_color, filled, contour_color, base, height):
        super(Rectangle, self).__init__(fill_color, filled, contour_color)
        self.base = base
        self.height = height

    def area(self):
        return self.base * self.height

    def perimeter(self):
        return 2 * (self.base + self.height)

class Circle(ChartObject):
    def __init__(self, fill_color, filled, contour_color, radius):
        super(Circle, self).__init__(fill_color, filled, contour_color)
        self.radius = radius

    def area(self):
        return pi * self.radius ** 2

    def perimeter(self):
        return 2 * pi * self.radius

class Triangle(ChartObject):
    def __init__(self, fill_color, filled, contour_color, base, height):
        super(Triangle, self).__init__(fill_color, filled, contour_color)
        self.base = base
        self.height = height

    def area(self):
        return self.base * self.height / 2

    def perimeter(self):
        return self.base + self.height + sqrt(self.base ** 2 + self.height ** 2)

