def cesar(palavra,chave):
    if chave>26:
        return "Error"
    cesar = ""
    for i in palavra:
        if "a"<=i<="z" or "A"<=i<="Z":
            if "a"<=chr(ord(i)+chave)<="z" or "A"<=chr(ord(i)+chave)<="Z": cesar += chr(ord(i)+chave)
            else: cesar += chr(ord(i)-(26-chave))
        else: cesar += i           
    return cesar

def desc(palavra,chave):
