    elemento1 = matriz[pos1 // 10][pos1 % 10]
    elemento2 = matriz[pos2 // 10][pos2 % 10]
    matriz[pos1 // 10][pos1 % 10] = elemento2
    matriz[pos2 // 10][pos2 % 10] = elemento1


def valorescentraisdoslados(linha, coluna):
    """Retornar posicoes do valores centrais dos lados."""
    if coluna is 0:
        return [(linha-1, coluna), (linha+1, coluna), (linha, coluna+1)]
    if coluna is 3:
        return [(linha-1, coluna), (linha+1, coluna), (linha, coluna-1)]


def valorescentraisdecima(linha, coluna):
    """Retornar posicoes dos valores centrais de cima."""
    if linha is 0:
        return [(linha, coluna-1), (linha, coluna+1), (linha+1, coluna)]
    if linha is 3:
        return [(linha, coluna-1), (linha, coluna+1), (linha-1, coluna)]


