"""Dado um inteiro positivo n, calcular e imprimir o valor da seguinte soma:
S = 1/n + 2/(n-1) + 3 / (n-2) ...."""

def sequence(n):
	s = 0;
	denominator = n;
	for i in range(1, n + 1):
		s += i/denominator
		denominator -= 1;
	return s;

