'''Dado 2 naturais m e n determinar, entre todos os pares de 
números naturais (x,y) tais que x < m e y < n, um par para o qual o
valor da expressão x*y - x**2 + y seja máximo e calcular também
esse máximo'''

def calculate(m, n):
	v1 = 0; #If x = 0, there's no solve for the problem
	v2 = 0; #If y = 0, there's no solve for the problem
	x = 0; 
	y = 0;
	res = 1; #If res = 1, there's no solve for the problem
	loop = int(m);
	if(n > m):
		loop = int(n);
	for j in range(1, loop):
		x = 0; #x needs to be reseted to enter to the loop again
		y += 1; 
		for i in range(1, loop):
			x += 1;
			if(x % 2 == 0 and y % 2 == 0):
				if(x*y - x**2 + y > res):
					res = x*y - x**2 + y;
					v1 = x;
					v2 = y;
	print('x = {} and y = {}' .format(v1, v2));
	return res;

